        self.check_statement([
            line("1", "A", "S", 10000),
            line("2", "A", "T", 30000),
            line("3", "B", "S", 30000),
            line("4", "A", "S", 15000),
            line("5", "A:B", "C", 30000),
            line("6", "A", "B:C", 30000),
        ], [750, 3000, 3000, 2250, 3000, 3000])

    def test_rounding_is_per_line(self):
        self.check_statement([
